def persistentize_path(value: Any) -> Path:
    """Move a legacy /content/pingo_training path under persistent storage."""
    path = Path(value)

    try:
        relative = path.resolve().relative_to(LEGACY_TRAINING_ROOT.resolve())
    except Exception:
        return path

    return TRAINING_ROOT / relative


